
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_xpbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_xpbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.312015458413114e+00, -4.230464117483375e+00, -4.116311734737552e+00, -3.958435826399987e+00, -3.743843728974838e+00, -3.459362669252810e+00, -3.095553989293152e+00, -2.653601326539061e+00, -2.153544941019192e+00, -1.632000944204507e+00, -1.105780985460717e+00, -7.120175688934687e-01, -6.028737525567812e-01, -5.032236183148051e-01, -3.739681954152858e-01, -2.482410085445502e-01, -1.393381321152491e-01, -5.254009167816235e-02, -1.150274501844534e-02, -1.294093313393645e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


